-- =====================================================================
-- 256 — Lote 1 LNME (2/4): perfis em public.drug_profiles (1/2)
-- ---------------------------------------------------------------------
-- Conteúdo autoral (não copiado), ancorado nos rótulos aprovados
-- DailyMed (setIDs validados na API — nenhum fictício) e corroborado
-- no Prontuário Terapêutico do INFARMED (11.ª ed., 2012).
-- Padrão 7.6: JOIN (VALUES) ON d.slug = v.slug + ON CONFLICT DO NOTHING.
-- Idempotente. Companheiras: 255 (drugs), 257 (perfis 2/2), 258/259
-- (farmacologia).
-- =====================================================================

INSERT INTO public.drug_profiles
  (drug_id, overview_public_pt, overview_public_en, overview_pro_pt, overview_pro_en,
   indications_pt, indications_en, side_effects_pt, side_effects_en,
   precautions_pt, precautions_en, source_pt, source_en, status)
SELECT d.id, v.overview_public_pt, v.overview_public_en, v.overview_pro_pt, v.overview_pro_en,
       v.indications_pt, v.indications_en, v.side_effects_pt, v.side_effects_en,
       v.precautions_pt, v.precautions_en, v.source_pt, v.source_en, 'published'
FROM public.drugs d
JOIN (VALUES
  ('albendazol',
   E'Albendazol é um comprimido anti-parasitário de largo espetro que elimina vermes intestinais (lombrigas, solitárias, oxiúros) e outros parasitas. É também usado no tratamento de quistos hidáticos e neurocisticercose sob supervisão médica.',
   E'Albendazole is a broad-spectrum antiparasitic tablet that eliminates intestinal worms (roundworms, tapeworms, pinworms) and other parasites. It is also used for hydatid cysts and neurocysticercosis under medical supervision.',
   E'Benzimidazol que se liga à β-tubulina dos parasitas, bloqueando a polimerização de microtúbulos e impedindo a captação de glicose — o verme morre por inanição energética. A absorção oral aumenta muito com refeição gordurosa; sofre metabolismo de primeira passagem a sulfoxido ativo (CYP3A4).',
   E'Benzimidazole that binds parasite β-tubulin, blocking microtubule polymerisation and glucose uptake — the worm dies of energy starvation. Oral absorption increases markedly with a fatty meal; undergoes first-pass metabolism to the active sulfoxide (CYP3A4).',
   E'• Desparasitação de nemátodos intestinais (Ascaris, ancilostomas, Enterobius, Trichuris)\n• Teníases e neurocisticercose (Taenia solium)\n• Equinococose quística (Echinococcus granulosus)\n• Giardíase (alternativa)\n• Filariose linfática (com dietilcarbamazina, em programas de saúde pública)',
   E'• Intestinal nematode deworming (Ascaris, hookworm, Enterobius, Trichuris)\n• Taeniasis and neurocysticercosis (Taenia solium)\n• Cystic echinococcosis (Echinococcus granulosus)\n• Giardiasis (alternative)\n• Lymphatic filariasis (with diethylcarbamazine, in public health programmes)',
   E'• Dor de cabeça, tonturas, náuseas, vómitos, dor abdominal\n• Elevação reversível das transaminases\n• Alopecia reversível (tratamentos prolongados)\n• Leucopenia/trombocitopenia (raro)\n• Reações meningéias e hipersensibilidade (raro)\n• Procure ajuda imediata se houver sinais de reação alérgica grave (dificuldade em respirar, inchaço do rosto/garganta).',
   E'• Headache, dizziness, nausea, vomiting, abdominal pain\n• Reversible transaminase elevation\n• Reversible alopecia (prolonged courses)\n• Leucopenia/thrombocytopenia (rare)\n• Meningeal reactions and hypersensitivity (rare)\n• Seek immediate help if there are signs of a severe allergic reaction (trouble breathing, face/throat swelling).',
   E'• Contraindicado na gravidez (primeiro trimestre) e durante a amamentação\n• Contracepção eficaz durante o tratamento e 1 mês depois\n• Monitorizar hemograma e enzimas hepáticas em cursos > 14 dias\n• Desparasitação em massa: evitar em grávidas e crianças < 1 ano',
   E'• Contraindicated in pregnancy (first trimester) and during breastfeeding\n• Effective contraception during treatment and for 1 month after\n• Monitor blood count and liver enzymes for courses > 14 days\n• Mass deworming: avoid in pregnant women and children < 1 year',
   E'Rótulo aprovado DailyMed/FDA — Albendazole Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8de337eb-92e1-15b5-e053-2a95a90ac4f1 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Albendazole Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8de337eb-92e1-15b5-e053-2a95a90ac4f1 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('mebendazol',
   E'Mebendazol é um comprimido anti-vermes usado no tratamento das infestações intestinais mais comuns: lombrigas, oxiúros, ancilostomas e tricocéfalos. Uma dose única resolve a maioria dos casos; por vezes repete-se ao fim de 2 semanas.',
   E'Mebendazole is a worm medicine tablet used to treat the most common intestinal infestations: roundworm, pinworm, hookworm and whipworm. A single dose resolves most cases; it is sometimes repeated after 2 weeks.',
   E'Benzimidazol de absorção sistémica mínima (biotransformação intestinal/hepática a metabolitos inativos) que inibe seletivamente a polimerização da β-tubulina do parasita, destruindo a microcanalização citoplasmática e bloqueando a utilização de glicose.',
   E'Benzimidazole with minimal systemic absorption (intestinal/hepatic biotransformation to inactive metabolites) that selectively inhibits parasite β-tubulin polymerisation, destroying cytoplasmic microtubules and blocking glucose utilisation.',
   E'• Enterobíase (oxiúros)\n• Ascaridíase (lombrigas)\n• Ancilostomíase\n• Tricuríase\n• Infestações mistas por nemátodos intestinais',
   E'• Enterobiasis (pinworm)\n• Ascariasis (roundworm)\n• Hookworm infection\n• Whipworm infection\n• Mixed intestinal nematode infestations',
   E'• Dor abdominal transitória, diarreia, flatulência (em infestações pesadas)\n• Náuseas, vómitos\n• Erupção cutânea e urticária (raro)\n• Elevação das transaminases (uso prolongado)\n• Procure ajuda imediata se houver sinais de reação alérgica grave (dificuldade em respirar, inchaço do rosto/garganta).',
   E'• Transient abdominal pain, diarrhoea, flatulence (heavy infestations)\n• Nausea, vomiting\n• Rash and urticaria (rare)\n• Transaminase elevation (prolonged use)\n• Seek immediate help if there are signs of a severe allergic reaction (trouble breathing, face/throat swelling).',
   E'• Contraindicado no 1.º trimestre da gravidez\n• Em infestações pesadas e cursos longos, monitorizar hemograma e enzimas hepáticas\n• Tratar simultaneamente os membros do agregado familiar na oxiuríase\n• Higiene das mãos e unhas para prevenir reinfestação',
   E'• Contraindicated in the 1st trimester of pregnancy\n• In heavy infestations and long courses, monitor blood count and liver enzymes\n• Treat household members simultaneously in pinworm infection\n• Hand and nail hygiene to prevent reinfection',
   E'Rótulo aprovado DailyMed/FDA — EMVERM (Mebendazole) Chewable Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=a8c46363-f739-4f6e-bca8-1ce5e8d3f78d — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — EMVERM (Mebendazole) Chewable Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=a8c46363-f739-4f6e-bca8-1ce5e8d3f78d — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('ivermectina',
   E'Ivermectina é um comprimido anti-parasitário usado contra oncocercose (cegueira dos rios), strongiloidíase e infestações por piolhos e ácaros da sarna. Atua paralisando os parasitas, que são depois eliminados pelo organismo.',
   E'Ivermectin is an antiparasitic tablet used against onchocerciasis (river blindness), strongyloidiasis and infestations with lice and scabies mites. It paralyses the parasites, which are then cleared by the body.',
   E'Avermectina que se liga a canais de cloro dependentes de glutamato nas células nervosas e musculares dos invertebrados, causando paralisia flácida e morte do parasita. Em humanos, os canais homólogos estão confinados ao SNC (a glicoproteína-P impede a entrada) — daí a boa segurança sistémica. Absorção aumenta com a refeição; metabolismo hepático (CYP3A4), meia-vida ~18 h.',
   E'Avermectin that binds glutamate-gated chloride channels in invertebrate nerve and muscle cells, causing flaccid paralysis and parasite death. In humans the homologous channels are confined to the CNS (P-glycoprotein excludes the drug) — hence good systemic safety. Absorption increases with food; hepatic metabolism (CYP3A4), half-life ~18 h.',
   E'• Oncocercose (Onchocerca volvulus)\n• Strongiloidíase (Strongyloides stercoralis)\n• Escabiose (crostosa e comum, alternativa ao tópico)\n• Pediculose (piolhos)\n• Filariose linfática e mansonelose (programas de saúde pública)',
   E'• Onchocerciasis (Onchocerca volvulus)\n• Strongyloidiasis (Strongyloides stercoralis)\n• Scabies (crusted and common, alternative to topical)\n• Pediculosis (lice)\n• Lymphatic filariasis and mansonellosis (public health programmes)',
   E'• Reações de Mazzotti na oncocercose (prurido, erupção, febre, adenopatias — resposta à morte dos microfilárias)\n• Tonturas, sonolência, tremores\n• Náuseas, diarreia, dor abdominal\n• Edema periférico, hipotensão (raro)\n• Convulsões (muito raro)\n• Procure ajuda imediata se houver sinais de reação alérgica grave (dificuldade em respirar, inchaço do rosto/garganta).',
   E'• Mazzotti reactions in onchocerciasis (itching, rash, fever, lymphadenopathy — response to microfilariae death)\n• Dizziness, drowsiness, tremor\n• Nausea, diarrhoea, abdominal pain\n• Peripheral oedema, hypotension (rare)\n• Seizures (very rare)\n• Seek immediate help if there are signs of a severe allergic reaction (trouble breathing, face/throat swelling).',
   E'• Em doses altas: vigilância neurológica (risco de depressão do SNC se a barreira hematoencefálica estiver comprometida)\n• Não confirmado para uso em crianças < 15 kg ou < 5 anos em algumas indicações\n• Na escabiose crostosa, associar a escabicida tópico e repetir doses\n• Evitar em casos com meningoencefalite ativa ou condições que aumentem a permeabilidade da BHE',
   E'• At high doses: neurological surveillance (risk of CNS depression if the blood-brain barrier is compromised)\n• Not confirmed for children < 15 kg or < 5 years in some indications\n• In crusted scabies, combine with topical scabicide and repeat doses\n• Avoid in active meningoencephalitis or conditions increasing BBB permeability',
   E'Rótulo aprovado DailyMed/FDA — STROMECTOL (Ivermectin) Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=681888c9-af79-4b7d-ae80-c3f4f6f1effd — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — STROMECTOL (Ivermectin) Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=681888c9-af79-4b7d-ae80-c3f4f6f1effd — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('pirantel',
   E'Pirantel é um anti-vermes em suspensão ou comprimido, usado sobretudo em crianças contra lombrigas, oxiúros e ancilostomas. Atua paralisando os vermes, que são expelidos naturalmente nas fezes.',
   E'Pyrantel is a worm medicine in suspension or tablet form, used mainly in children against roundworm, pinworm and hookworm. It paralyses the worms, which are then naturally expelled in the stool.',
   E'Agonista nicotínico nos recetores dos nemátodos, provocando despolarização persistente e paralisia espástica do verme; é pobremente absorvido por via oral (máx. plasmático em 1–3 h, metabolismo hepático a N-metil-pirantel), o que concentra a ação no lúmen intestinal. Não é indicado na fase larvar tissular.',
   E'Nicotinic receptor agonist in nematodes, causing persistent depolarisation and spastic paralysis of the worm; poorly absorbed orally (peak plasma in 1–3 h, hepatic metabolism to N-methyl-pyrantel), concentrating its action in the intestinal lumen. Not indicated for tissue larval stages.',
   E'• Ascaridíase (lombrigas)\n• Enterobíase (oxiúros)\n• Ancilostomíase\n• Infestações mistas por nemátodos intestinais',
   E'• Ascariasis (roundworm)\n• Enterobiasis (pinworm)\n• Hookworm infection\n• Mixed intestinal nematode infestations',
   E'• Náuseas, vómitos, cólicas, diarreia\n• Anorexia transitória\n• Cefaleias, tonturas, sonolência\n• Erupção cutânea (raro)\n• Elevação das transaminases (raro)\n• Procure ajuda imediata se houver sinais de reação alérgica grave (dificuldade em respirar, inchaço do rosto/garganta).',
   E'• Nausea, vomiting, cramps, diarrhoea\n• Transient anorexia\n• Headache, dizziness, drowsiness\n• Rash (rare)\n• Transaminase elevation (rare)\n• Seek immediate help if there are signs of a severe allergic reaction (trouble breathing, face/throat swelling).',
   E'• Uso seguro em crianças a partir de 1 ano (doses por peso)\n• Repetir a dose ao fim de 2 semanas na oxiuríase\n• Precaução na insuficiência hepática\n• Higiene ambiental e do agregado familiar na oxiuríase',
   E'• Safe in children from 1 year (weight-based dosing)\n• Repeat dose after 2 weeks in pinworm infection\n• Caution in hepatic impairment\n• Environmental and household hygiene in pinworm infection',
   E'Rótulo DailyMed/FDA — PINWORM MEDICINE (Pyrantel Pamoate) Suspension: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f23d5092-48ca-46c4-830a-c34d0a3a7f57 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA label — PINWORM MEDICINE (Pyrantel Pamoate) Suspension: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f23d5092-48ca-46c4-830a-c34d0a3a7f57 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('oxitocina',
   E'Oxitocina é uma hormona administrada por injeção (geralmente no hospital) que provoca contrações do útero. Serve para induzir ou reforçar o trabalho de parto e, após o nascimento, para prevenir e tratar hemorragias uterinas.',
   E'Oxytocin is a hormone given by injection (usually in hospital) that makes the uterus contract. It is used to induce or augment labour and, after birth, to prevent and treat uterine bleeding.',
   E'Nonapéptido sintético análogo da hormona hipofisária que se liga aos recetores de oxitocina miometriais, aumentando o cálcio intracelular e a contratilidade uterina. A resposta é dose-dependente e aumenta progressivamente com a gestação (sensibilização dos recetores). Meia-vida curta (3–5 min) — perfusão IV contínua para controlo fino; efeito antidiurético em doses altas.',
   E'Synthetic nonapeptide analogue of the pituitary hormone that binds myometrial oxytocin receptors, raising intracellular calcium and uterine contractility. The response is dose-dependent and increases progressively with gestation (receptor sensitisation). Short half-life (3–5 min) — continuous IV infusion for fine control; antidiuretic effect at high doses.',
   E'• Indução do trabalho de parto (por razões médicas ou obstétricas)\n• Reforço do trabalho de parto ineficaz\n• Prevenção e tratamento da hemorragia pós-parto por atonia uterina\n• Gestação extrauterina e abortamento incompleto (gestão médica)',
   E'• Induction of labour (for medical or obstetric reasons)\n• Augmentation of ineffective labour\n• Prevention and treatment of postpartum haemorrhage from uterine atony\n• Ectopic pregnancy and incomplete abortion (medical management)',
   E'• Contrações uterinas excessivas (taissistolia) e sofrimento fetal\n• Hipotensão, taquicardia (especialmente com perfusão rápida)\n• Retenção hídrica e hiponatremia (perfusões prolongadas em doses altas)\n• Náuseas, vómitos\n• Hemorragia pós-parto (doses inadequadas)\n• Procure ajuda imediata se houver sangramento abundante, dor forte ou sinais de sofrimento fetal.',
   E'• Excessive uterine contractions (tachysystole) and fetal distress\n• Hypotension, tachycardia (especially with rapid infusion)\n• Water retention and hyponatraemia (prolonged high-dose infusions)\n• Nausea, vomiting\n• Postpartum haemorrhage (inadequate dosing)\n• Seek immediate help if there is heavy bleeding, severe pain or signs of fetal distress.',
   E'• Apenas em ambiente com monitorização obstétrica contínua (CTG)\n• Diluir sempre para perfusão; nunca bólus IV não diluído (hipotensão brusca)\n• Precaução em cesariana anterior, multiparidade e apresentações anómalas\n• Vigiar balanço hídrico em infusões prolongadas',
   E'• Only in a setting with continuous obstetric monitoring (CTG)\n• Always dilute for infusion; never undiluted IV bolus (abrupt hypotension)\n• Caution with previous caesarean, grand multiparity and malpresentations\n• Monitor fluid balance in prolonged infusions',
   E'Rótulo aprovado DailyMed/FDA — PITOCIN (Oxytocin) Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=6e5a66fc-e507-497c-b5ce-44a8c95898ad — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — PITOCIN (Oxytocin) Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=6e5a66fc-e507-497c-b5ce-44a8c95898ad — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('misoprostol',
   E'Misoprostol é um comprimido análogo da prostaglandina E1 que provoca contrações do útero e protege a mucosa gástrica. Usa-se na indução do parto (com precauções), no abortamento médico, no tratamento de hemorragia pós-parto e na prevenção de úlceras por AINE.',
   E'Misoprostol is a prostaglandin E1 analogue tablet that makes the uterus contract and protects the stomach lining. It is used in labour induction (with precautions), medical abortion, postpartum haemorrhage treatment and NSAID ulcer prevention.',
   E'Análogo metilado da PGE1 com meia-vida longa e boa estabilidade à temperatura ambiente — vantagem logística decisiva. Deacarboxilação rápida a ácido misoprostólico ativo (máx. 30–60 min). Liga-se a recetores EP do miométrio (contrações e amolecimento cervical) e EP3 gástricos (redução da secreção de HCl e aumento do muco). Biodisponibilidade maior por via vaginal/sublingual do que oral.',
   E'Methylated PGE1 analogue with long half-life and good room-temperature stability — a decisive logistical advantage. Rapid de-esterification to active misoprostol acid (peak 30–60 min). Binds myometrial EP receptors (contractions and cervical ripening) and gastric EP3 (reduced HCl secretion and increased mucus). Higher bioavailability by vaginal/sublingual route than oral.',
   E'• Gestão médica do abortamento (isolado ou com mifepristona)\n• Indução do parto com colo imaturo (dose baixa, com vigilância obstétrica)\n• Prevenção e tratamento da hemorragia pós-parto por atonia uterina\n• Prevenção de úlceras gástricas e duodenais em doentes sob AINE (indicação original)',
   E'• Medical management of abortion (alone or with mifepristone)\n• Labour induction with unfavourable cervix (low dose, with obstetric monitoring)\n• Prevention and treatment of postpartum haemorrhage from uterine atony\n• Prevention of gastric and duodenal ulcers in patients on NSAIDs (original indication)',
   E'• Diarreia dose-dependente (a queixa mais comum na indicação GI)\n• Dor abdominal, náuseas, flatulência, dispepsia\n• Sangramento vaginal aumentado, cólicas\n• Febre e arrepios transitórios (via vaginal/sublingual em doses obstétricas)\n• Contrações uterinas excessivas (na indução, sobretudo com doses repetidas precoces)\n• Procure ajuda imediata se houver sangramento abundante ou febre persistente.',
   E'• Dose-dependent diarrhoea (the most common complaint in the GI indication)\n• Abdominal pain, nausea, flatulence, dyspepsia\n• Increased vaginal bleeding, cramps\n• Transient fever and chills (vaginal/sublingual route at obstetric doses)\n• Excessive uterine contractions (in induction, especially with early repeated doses)\n• Seek immediate help if there is heavy bleeding or persistent fever.',
   E'• CONTRAINDICADO na gravidez quando usado para gastroproteção (abortífero)\n• Na indução do parto: dose baixa (25 µg), intervalo ≥ 4–6 h, vigilância CTG\n• Informar sobre contracepção fiável durante o tratamento com AINE\n• Não substituir a oxitocina na profilaxia rotineira da HPP quando disponível',
   E'• CONTRAINDICATED in pregnancy when used for gastroprotection (abortifacient)\n• In labour induction: low dose (25 µg), interval ≥ 4–6 h, CTG monitoring\n• Counsel on reliable contraception during NSAID treatment\n• Do not replace oxytocin for routine PPH prophylaxis when available',
   E'Rótulo aprovado DailyMed/FDA — CYTOTEC (Misoprostol) Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4ab12da7-5731-4e06-bf1c-bc3f2e711f12 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — CYTOTEC (Misoprostol) Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4ab12da7-5731-4e06-bf1c-bc3f2e711f12 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('metilergometrina',
   E'Metilergometrina é um medicamento que faz o útero contrair de forma firme e prolongada. Administra-se após o parto (por via oral ou injetável) para tratar hemorragias causadas por má contração uterina.',
   E'Methylergometrine is a medicine that makes the uterus contract firmly and for a long time. It is given after childbirth (by mouth or injection) to treat bleeding caused by poor uterine contraction.',
   E'Alcaloide semissintético do ergot que age como agonista parcial dos recetores alfa-1-adrenérgicos e de 5-HT2 do miométrio, aumentando o tónus basal e a frequência de contrações uterinas — efeito mais prolongado e menos vasopressor que a ergotamina. Ação em minutos (IV) a 30 min (oral); duração de horas.',
   E'Semi-synthetic ergot alkaloid acting as partial agonist at uterine alpha-1-adrenergic and 5-HT2 receptors, raising basal tone and the frequency of uterine contractions — longer-lasting and less vasopressor than ergotamine. Onset in minutes (IV) to 30 min (oral); duration of hours.',
   E'• Tratamento e prevenção da hemorragia pós-parto por atonia uterina\n• Gestão do abortamento incompleto\n• Controlo do sangramento uterino no pós-parto/pós-aborto',
   E'• Treatment and prevention of postpartum haemorrhage from uterine atony\n• Management of incomplete abortion\n• Control of postpartum/post-abortion uterine bleeding',
   E'• Náuseas, vómitos, dor abdominal\n• Hipertensão transitória, cefaleias, tonturas\n• Vasoconstrição periférica (frio nas extremidades)\n• Angina e espasmo coronário (raro; evitar em cardiopatas)\n• Cólica e isquemia intestinal (raro)\n• Procure ajuda imediata se houver dor no peito, extremidades frias/azuladas ou sangramento abundante.',
   E'• Nausea, vomiting, abdominal pain\n• Transient hypertension, headache, dizziness\n• Peripheral vasoconstriction (cold extremities)\n• Angina and coronary spasm (rare; avoid in cardiac patients)\n• Intestinal colic and ischaemia (rare)\n• Seek immediate help if there is chest pain, cold/bluish extremities or heavy bleeding.',
   E'• CONTRAINDICADO na gravidez (antes do descolamento da placenta), hipertensão, pré-eclâmpsia e doença vascular oclusiva\n• Não administrar antes da expulsão da placenta\n• Evitar na amamentação (uso prolongado: risco de ergotismo no lactente)\n• Não associar a outros vasoconstritores (risco aditivo)',
   E'• CONTRAINDICATED in pregnancy (before placental delivery), hypertension, pre-eclampsia and occlusive vascular disease\n• Do not give before delivery of the placenta\n• Avoid in breastfeeding (prolonged use: ergotism risk for the infant)\n• Do not combine with other vasoconstrictors (additive risk)',
   E'Rótulo aprovado DailyMed/FDA — METHERGINE (Methylergonovine Maleate) Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3f04ca06-fe52-46d6-96cd-2e77ef6fa36f — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — METHERGINE (Methylergonovine Maleate) Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3f04ca06-fe52-46d6-96cd-2e77ef6fa36f — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('metildopa',
   E'Metildopa é um comprimido anti-hipertensivo de preferência histórica na hipertensão da gravidez, por ser seguro para o feto. Continua a ser um dos primeiros fármacos de escolha neste contexto em muitos países.',
   E'Methyldopa is an antihypertensive tablet historically preferred in pregnancy hypertension because it is safe for the fetus. It remains a first-choice option in this setting in many countries.',
   E'Pseudoaminoácido convertido no SNC em α-metil-noradrenalina, agonista alfa-2 central que reduz o tónus simpático e a resistência vascular periférica sem reduzir o fluxo placentário. Início em 6–8 h, pico em 2 dias, duração 24–48 h. Possíveis efeitos sedativos centrais; liver injury idiossincrático raro.',
   E'Pseudo-amino acid converted in the CNS to α-methylnoradrenaline, a central alpha-2 agonist that reduces sympathetic tone and peripheral vascular resistance without reducing placental flow. Onset 6–8 h, peak at 2 days, duration 24–48 h. Possible central sedative effects; rare idiosyncratic liver injury.',
   E'• Hipertensão arterial na gravidez (pré-eclâmpsia moderada e HTA crónica gestacional) — indicação de referência\n• Hipertensão essencial (quando outros fármacos não são tolerados/adequados)',
   E'• Arterial hypertension in pregnancy (moderate pre-eclampsia and gestational chronic HTN) — reference indication\n• Essential hypertension (when other drugs are not tolerated/suitable)',
   E'• Sonolência e sedação (sobretudo nas primeiras 48–72 h)\n• Boca seca, edema, ganho ponderal\n• Tonturas e hipotensão ortostática\n• Depressão (dose-dependente; evitar em histórico psiquiátrico)\n• Hepatite medicamentosa, anemia hemolítica com teste de Coombs positivo (raro, reversível)\n• Procure ajuda imediata se houver icterícia, febre com dor muscular ou hematomas fáceis.',
   E'• Drowsiness and sedation (especially in the first 48–72 h)\n• Dry mouth, oedema, weight gain\n• Dizziness and orthostatic hypotension\n• Depression (dose-dependent; avoid with psychiatric history)\n• Drug-induced hepatitis, Coombs-positive haemolytic anaemia (rare, reversible)\n• Seek immediate help if there is jaundice, fever with muscle pain or easy bruising.',
   E'• Monitorizar hemograma, teste de Coombs e transaminases (basal e periódico)\n• Efeitos exagerados se associado a outros anti-hipertensores centrais ou anestésicos\n• Rever a terapêutica no pós-parto (muitos doentes podem mudar de fármaco)\n• Precaução na insuficiência hepática e renal',
   E'• Monitor blood count, Coombs test and transaminases (baseline and periodic)\n• Exaggerated effects when combined with other central antihypertensives or anaesthetics\n• Reassess therapy postpartum (many patients can switch drugs)\n• Caution in hepatic and renal impairment',
   E'Rótulo aprovado DailyMed/FDA — Methyldopa Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9e22e1d8-04ec-4b67-92ea-b09c706f2703 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Methyldopa Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9e22e1d8-04ec-4b67-92ea-b09c706f2703 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('hidralazina',
   E'Hidralazina é um vasodilatador usado por via oral na hipertensão (incluindo na gravidez) e por via injetável na urgência hipertensiva e na pré-eclâmpsia grave. Baixa a pressão relaxando diretamente os músculos das artérias.',
   E'Hydralazine is a vasodilator used by mouth for hypertension (including in pregnancy) and by injection for hypertensive emergencies and severe pre-eclampsia. It lowers blood pressure by directly relaxing artery muscles.',
   E'Vasodilatador arteriolar direto que abre canais de potássio e ativa guanilato ciclase no músculo liso vascular, reduzindo a resistência periférica; gera taquicardia reflexa e retenção de sódio, pelo que se associa habitualmente a betabloqueador e diurético. Metabolismo hepático extenso (acetilação variável — acetiladores lentos têm mais efeitos adversos); meia-vida 3–7 h mas ação farmacológica mais longa. Lupus induzido por fármaco dose-dependente.',
   E'Direct arteriolar vasodilator that opens potassium channels and activates vascular smooth muscle guanylate cyclase, lowering peripheral resistance; produces reflex tachycardia and sodium retention, hence usually combined with a beta-blocker and diuretic. Extensive hepatic metabolism (variable acetylation — slow acetylators have more adverse effects); half-life 3–7 h but pharmacological action longer. Dose-dependent drug-induced lupus.',
   E'• Hipertensão essencial (em associação, quando outros fármacos não bastam)\n• Hipertensão na gravidez e pré-eclâmpsia grave (IV, na urgência)\n• Insuficiência cardíaca (combinada com ISDN, em doentes específicos)',
   E'• Essential hypertension (in combination, when other drugs are insufficient)\n• Hypertension in pregnancy and severe pre-eclampsia (IV, in emergency)\n• Heart failure (combined with ISDN, in selected patients)',
   E'• Cefaleias, tonturas, palpitações, taquicardia reflexa\n• Rubor, congestão nasal, edema\n• Hipotensão ortostática\n• Síndrome lupus-like (artralgias, erupção, ANA positivo) — dose e tempo dependentes\n• Neuropatia periférica (raro, por consumo de piridoxina)\n• Procure ajuda imediata se houver dor no peito, desmaio ou dispneia súbita.',
   E'• Headache, dizziness, palpitations, reflex tachycardia\n• Flushing, nasal congestion, oedema\n• Orthostatic hypotension\n• Lupus-like syndrome (arthralgia, rash, positive ANA) — dose and time dependent\n• Peripheral neuropathy (rare, from pyridoxine depletion)\n• Seek immediate help if there is chest pain, fainting or sudden breathlessness.',
   E'• Associar sempre a betabloqueador para atenuar taquicardia reflexa (sobretudo em cardiopatas)\n• Ajustar dose na insuficiência renal\n• Precaução em cardiopatia isquémica, disseção de aneurisma e insuficiência mitral reumática\n• Rever sintomas articulares/cutâneos que sugiram lupus induzido',
   E'• Always combine with a beta-blocker to blunt reflex tachycardia (especially in cardiac patients)\n• Adjust dose in renal impairment\n• Caution in ischaemic heart disease, aneurysm dissection and rheumatic mitral insufficiency\n• Review joint/skin symptoms suggesting drug-induced lupus',
   E'Rótulo aprovado DailyMed/FDA — Hydralazine Hydrochloride Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=47ad263b-ad3d-4f98-b0aa-d9e82ab6cb67 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Hydralazine Hydrochloride Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=47ad263b-ad3d-4f98-b0aa-d9e82ab6cb67 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('lidocaina',
   E'Lidocaína é um anestésico local aplicado por injeção, spray ou adesivo para adormecer a pele, gengivas e mucosas em pequenas cirurgias e procedimentos. Em doses controladas também serve como antiarrítmico no hospital.',
   E'Lidocaine is a local anaesthetic given by injection, spray or patch to numb skin, gums and mucosa in minor surgery and procedures. In controlled doses it is also used as a hospital antiarrhythmic.',
   E'Amida estabilizadora de membrana que bloqueia canais de sódio voltagem-dependentes — a condução nociceptiva é interrompida localmente. Início de ação em segundos a minutos; duração 30–120 min (mais com epinefrina, que reduz a absorção e prolonga o efeito). Metabolismo hepático rápido (CYP1A2/3A4, meia-vida 1,5–2 h); toxicidade sistémica proporcional à absorção e perfusão do local.',
   E'Amide membrane stabiliser that blocks voltage-gated sodium channels — nociceptive conduction is interrupted locally. Onset in seconds to minutes; duration 30–120 min (longer with epinephrine, which reduces absorption and prolongs effect). Rapid hepatic metabolism (CYP1A2/3A4, half-life 1.5–2 h); systemic toxicity proportional to absorption and site perfusion.',
   E'• Infiltração e bloqueio nervoso local em pequenas cirurgias e suturas\n• Anestesia tópica de mucosas (endoscopia, intubação)\n• Antiarrítmico IV na taquicardia ventricular (ambiente hospitalar)\n• Dor neuropática localizada (adesivos tópicos)',
   E'• Local infiltration and nerve block in minor surgery and suturing\n• Topical anaesthesia of mucosa (endoscopy, intubation)\n• IV antiarrhythmic in ventricular tachycardia (hospital setting)\n• Localised neuropathic pain (topical patches)',
   E'• Dormência prolongada do local, formigueiro\n• Reação vagaal (bradicardia, palidez) — não é alergia\n• Fenómenos de hipersensibilidade (raro em amidas)\n• Toxicidade sistémica (dose alta/intravascular): zumbidos, gosto metálico, tremores, convulsões, arritmias\n• Metemoglobinemia (com benzocaína em produtos combinados)\n• Procure ajuda imediata se houver zumbidos, confusão, convulsões ou palpitções após a aplicação.',
   E'• Prolonged numbness at the site, tingling\n• Vasovagal reaction (bradycardia, pallor) — not an allergy\n• Hypersensitivity phenomena (rare among amides)\n• Systemic toxicity (high dose/intravascular): tinnitus, metallic taste, tremors, seizures, arrhythmias\n• Methaemoglobinaemia (with benzocaine in combination products)\n• Seek immediate help if there is ringing in the ears, confusion, seizures or palpitations after application.',
   E'• Respeitar a dose máxima por peso (3 mg/kg sem epinefrina; ~7 mg/kg com epinefrina em adultos saudáveis)\n• Aspirar antes de injetar para evitar injeção intravascular\n• Reduzir dose em insuficiência hepática, insuficiência cardíaca e idosos\n• Ter sempre lipídios 20% disponível em ambiente de anestesia (resgate da toxicidade sistémica)',
   E'• Respect the maximum dose by weight (3 mg/kg without epinephrine; ~7 mg/kg with epinephrine in healthy adults)\n• Aspirate before injecting to avoid intravascular injection\n• Reduce dose in liver failure, heart failure and the elderly\n• Keep 20% lipid emulsion available in anaesthesia settings (LAST rescue)',
   E'Rótulo aprovado DailyMed/FDA — XYLOCAINE (Lidocaine Hydrochloride, Epinephrine Bitartrate) Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9e8d0318-b2fe-4084-aedf-de97f61605a8 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — XYLOCAINE (Lidocaine Hydrochloride, Epinephrine Bitartrate) Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9e8d0318-b2fe-4084-aedf-de97f61605a8 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('midazolam',
   E'Midazolam é um sedativo de ação rápida administrado por via oral, intravenosa ou intramuscular para acalmar o doente antes de procedimentos, induzir anestesia ou parar crises convulsivas prolongadas. Só deve ser usado com pessoal treinado e equipamento de reanimação disponível.',
   E'Midazolam is a fast-acting sedative given by mouth, intravenously or intramuscularly to calm patients before procedures, induce anaesthesia or stop prolonged seizures. It should only be used by trained staff with resuscitation equipment available.',
   E'Benzodiazepina imidazólica de ultracurta duração: potencia a ação do GABA no recetor GABA-A, produzindo ansiólise, sedação, amnésia anterógrada, hipnose e efeito anticonvulsivo. Absorção oral rápida (mas biotransformação de primeira passagem 40%), início em 2–3 min por IV; meia-vida de eliminação 1,5–3,5 h (mais curta que as outras benzodiazepinas de hipnose). Metabolismo hepático CYP3A4 a α-hidroximidazolam ativo, glucuronidado e excretado na urina.',
   E'Ultra-short-acting imidazobenzodiazepine: potentiates GABA at the GABA-A receptor, producing anxiolysis, sedation, anterograde amnesia, hypnosis and anticonvulsant effect. Rapid oral absorption (but 40% first-pass metabolism), onset in 2–3 min IV; elimination half-life 1.5–3.5 h (shorter than other hypnotic benzodiazepines). Hepatic CYP3A4 metabolism to active α-hydroxymidazolam, glucuronidated and excreted in urine.',
   E'• Sedação pré-operatória e amnésia em procedimentos (endoscopia, radiologia intervencionista)\n• Indução da anestesia geral\n• Tratamento de estado de mal epiléptico (buccal/intranasal/intramuscular quando não há acesso IV)\n• Sedação em cuidados intensivos (perfusão contínua)',
   E'• Preoperative sedation and procedural amnesia (endoscopy, interventional radiology)\n• Induction of general anaesthesia\n• Treatment of status epilepticus (buccal/intranasal/intramuscular when IV access is unavailable)\n• ICU sedation (continuous infusion)',
   E'• Sonolência prolongada, amnésia do período\n• Depressão respiratória (dose-dependente; risco grave em idosos e com opioides)\n• Hipotensão\n• Agitação paradoxal (sobretudo em crianças e idosos)\n• Náuseas, vómitos, tosse\n• Procure ajuda imediata se houver dificuldade em respirar, lábios azulados ou sonolência excessiva após a sedação.',
   E'• Prolonged drowsiness, period amnesia\n• Respiratory depression (dose-dependent; serious risk in the elderly and with opioids)\n• Hypotension\n• Paradoxical agitation (especially in children and the elderly)\n• Nausea, vomiting, cough\n• Seek immediate help if there is trouble breathing, blue lips or excessive drowsiness after sedation.',
   E'• NUNCA usar sem monitorização (SpO2, ritmo cardíaco) e pessoal treinado em manejo de via aérea\n• Reduzir 50% a dose em idosos, debilitados e com CYP3A4 inibido (claritromicina, azólicos)\n• Ter flumazenil e via aérea disponíveis\n• Evitar em glaucoma de ângulo fechado e apneia do sono não tratada',
   E'• NEVER use without monitoring (SpO2, heart rhythm) and staff trained in airway management\n• Reduce dose by 50% in the elderly, frail patients and CYP3A4-inhibited (clarithromycin, azoles)\n• Have flumazenil and airway available\n• Avoid in narrow-angle glaucoma and untreated sleep apnoea',
   E'Rótulo aprovado DailyMed/FDA — MIDAZOLAM (Midazolam Hydrochloride) Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d9305142-417d-4d8c-9a23-f9a1b6771cac — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — MIDAZOLAM (Midazolam Hydrochloride) Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d9305142-417d-4d8c-9a23-f9a1b6771cac — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('atropina',
   E'Atropina é uma injeção usada na urgência para acelerar o coração quando bate demasiado devagar (bradicardia sintomática) e para reduzir secreções antes de anestesias. Também existe em gotas para dilatar a pupila no exame oftalmológico.',
   E'Atropine is an injection used in emergencies to speed up the heart when it beats too slowly (symptomatic bradycardia) and to reduce secretions before anaesthesia. Eye drops also exist to dilate the pupil during eye examinations.',
   E'Alcaloide natural (Atropa belladonna) que age como antagonista competitivo dos recetores muscarínicos — bloqueia os efeitos parassimpáticos (vago) no coração (aumenta a frequência), no trato respiratório (reduz secreções), no TGI (diminui o peristaltismo) e na pupila (midríase, cicloplegia). Meia-vida 2–5 h; efeito oftalmológico prolongado (dias).',
   E'Natural alkaloid (Atropa belladonna) acting as a competitive antagonist at muscarinic receptors — blocks parasympathetic (vagal) effects in the heart (raises rate), airway (reduces secretions), GI tract (decreases motility) and pupil (mydriasis, cycloplegia). Half-life 2–5 h; ophthalmic effect prolonged (days).',
   E'• Bradicardia sintomática (primeira linha na RCP, algoritmo de bradicardia)\n• Redução de secreções e proteção vagal na pré-medicação anestésica\n• Antídoto em intoxicação por organofosforados e inibidores da colinesterase (militares e agrícolas)\n• Midríase/cicloplegia diagnóstica e terapêutica (colírio)',
   E'• Symptomatic bradycardia (first line in ACLS bradycardia algorithm)\n• Reduction of secretions and vagal protection in anaesthetic premedication\n• Antidote in organophosphate and cholinesterase-inhibitor poisoning (military and agricultural)\n• Diagnostic and therapeutic mydriasis/cycloplegia (eye drops)',
   E'• Taquicardia, palpitações\n• Boca seca, visão turva, midríase, fotofobia\n• Retenção urinária e obstipação\n• Confusão e agitação (sobretudo em idosos)\n• Glaucoma agudo em predispostos (com colírio)\n• Procure ajuda imediata se houver dor ocular intensa, retenção urinária ou confusão grave.',
   E'• Tachycardia, palpitations\n• Dry mouth, blurred vision, mydriasis, photophobia\n• Urinary retention and constipation\n• Confusion and agitation (especially in the elderly)\n• Acute glaucoma in predisposed patients (with eye drops)\n• Seek immediate help if there is severe eye pain, urinary retention or severe confusion.',
   E'• Precaução em idosos (risco de delirium) e obstrução do trato urinário/gastrintestinal\n• Evitar em taquiarritmias, insuficiência cardíaca hipercinética e glaucoma de ângulo fechado\n• No antídoto de intoxicação anticolinérgica: fisostigmina (ambiente hospitalar)\n• Informar o doente que a midríasis após colírio dura dias',
   E'• Caution in the elderly (delirium risk) and urinary/GI tract obstruction\n• Avoid in tachyarrhythmias, hyperkinetic heart failure and narrow-angle glaucoma\n• Antidote for anticholinergic toxicity: physostigmine (hospital setting)\n• Warn patients that pupil dilation after eye drops lasts days',
   E'Rótulo aprovado DailyMed/FDA — ATROPINE SULFATE Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8663ff94-8bea-4061-9fd5-3ab2e85e862e — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — ATROPINE SULFATE Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8663ff94-8bea-4061-9fd5-3ab2e85e862e — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)')
) AS v(slug, overview_public_pt, overview_public_en, overview_pro_pt, overview_pro_en,
       indications_pt, indications_en, side_effects_pt, side_effects_en,
       precautions_pt, precautions_en, source_pt, source_en)
ON d.slug = v.slug
ON CONFLICT (drug_id) DO NOTHING;
